-- 约定：本表由 load_to_mysql.py --init 一次性建表（init 只跑一次）；用 CREATE ... IF NOT EXISTS，勿加回 DROP TABLE（会清空真实库数据）。
CREATE TABLE IF NOT EXISTS telecom_financials
(
    company_code                                                  CHAR(10)       NOT NULL,
    fiscal_year                                                   SMALLINT       NOT NULL COMMENT '报告期(年度)',
    total_operating_revenue                                       DECIMAL(28, 4) NULL COMMENT '营业总收入(元)',
    operating_cost                                                DECIMAL(28, 4) NULL COMMENT '营业成本(元)',
    total_operating_cost                                          DECIMAL(28, 4) NULL COMMENT '营业总成本(元)',
    taxes_and_surcharges                                          DECIMAL(28, 4) NULL COMMENT '税金及附加(元)',
    selling_expenses                                              DECIMAL(28, 4) NULL COMMENT '销售费用(元)',
    general_admin_expenses                                        DECIMAL(28, 4) NULL COMMENT '管理费用/业务及管理费(元)',
    financial_expenses                                            DECIMAL(28, 4) NULL COMMENT '财务费用(元)',
    research_and_development_expenses                             DECIMAL(28, 4) NULL COMMENT '研发费用(元)',
    credit_impairment_loss                                        DECIMAL(28, 4) NULL COMMENT '信用减值损失(元；水泥/地产/运营商源值以负数表示损失)',
    asset_impairment_loss                                         DECIMAL(28, 4) NULL COMMENT '资产减值损失(元；水泥/地产/运营商源值以负数表示损失)',
    investment_income                                             DECIMAL(28, 4) NULL COMMENT '投资收益(元)',
    investment_income_from_associates_and_joint_ventures          DECIMAL(28, 4) NULL COMMENT '对联营企业和合营企业的投资收益(元)',
    other_income                                                  DECIMAL(28, 4) NULL COMMENT '其他收益(元)',
    income_tax_expense                                            DECIMAL(28, 4) NULL COMMENT '所得税费用(元)',
    net_profit_excluding_non_recurring_items_attr_parent          DECIMAL(28, 4) NULL COMMENT '扣除非经常性损益后归母净利润(元)',
    net_profit_attr_non_controlling_interests                     DECIMAL(28, 4) NULL COMMENT '少数股东损益(元)',
    cash_and_bank_balances                                        DECIMAL(28, 4) NULL COMMENT '货币资金(元)',
    trading_financial_assets                                      DECIMAL(28, 4) NULL COMMENT '交易性金融资产(元)',
    notes_and_accounts_receivable                                 DECIMAL(28, 4) NULL COMMENT '应收票据及应收账款(元)',
    prepayments                                                   DECIMAL(28, 4) NULL COMMENT '预付款项(元)',
    other_receivables                                             DECIMAL(28, 4) NULL COMMENT '其他应收款合计(元)',
    inventories                                                   DECIMAL(28, 4) NULL COMMENT '存货(元)',
    long_term_equity_investments                                  DECIMAL(28, 4) NULL COMMENT '长期股权投资(元)',
    fixed_assets                                                  DECIMAL(28, 4) NULL COMMENT '固定资产(元)',
    construction_in_progress                                      DECIMAL(28, 4) NULL COMMENT '在建工程(元)',
    right_of_use_assets                                           DECIMAL(28, 4) NULL COMMENT '使用权资产(元)',
    intangible_assets                                             DECIMAL(28, 4) NULL COMMENT '无形资产(元)',
    goodwill                                                      DECIMAL(28, 4) NULL COMMENT '商誉(元)',
    total_current_assets                                          DECIMAL(28, 4) NULL COMMENT '流动资产合计(元)',
    short_term_borrowings                                         DECIMAL(28, 4) NULL COMMENT '短期借款(元)',
    short_term_bonds_payable                                      DECIMAL(28, 4) NULL COMMENT '应付短期债券(元)',
    notes_and_accounts_payable                                    DECIMAL(28, 4) NULL COMMENT '应付票据及应付账款(元)',
    contract_liabilities                                          DECIMAL(28, 4) NULL COMMENT '合同负债(元)',
    advances_from_customers                                       DECIMAL(28, 4) NULL COMMENT '预收款项(元)',
    non_current_liabilities_due_within_one_year                   DECIMAL(28, 4) NULL COMMENT '一年内到期的非流动负债(元)',
    total_current_liabilities                                     DECIMAL(28, 4) NULL COMMENT '流动负债合计(元)',
    long_term_borrowings                                          DECIMAL(28, 4) NULL COMMENT '长期借款(元)',
    bonds_payable                                                 DECIMAL(28, 4) NULL COMMENT '应付债券(元)',
    lease_liabilities                                             DECIMAL(28, 4) NULL COMMENT '租赁负债(元)',
    total_non_current_liabilities                                 DECIMAL(28, 4) NULL COMMENT '非流动负债合计(元)',
    perpetual_bonds                                               DECIMAL(28, 4) NULL COMMENT '其他权益工具-其中永续债(元)',
    other_equity_instruments                                      DECIMAL(28, 4) NULL COMMENT '其他权益工具(元)',
    equity_attr_non_controlling_interests                         DECIMAL(28, 4) NULL COMMENT '少数股东权益(元)',
    undistributed_profits                                         DECIMAL(28, 4) NULL COMMENT '未分配利润(元)',
    cash_received_from_sales_and_services                         DECIMAL(28, 4) NULL COMMENT '销售商品、提供劳务收到的现金(元)',
    cash_paid_for_long_term_assets                                DECIMAL(28, 4) NULL COMMENT '购建固定资产、无形资产和其他长期资产支付的现金(元)',
    provision_for_asset_impairment                                DECIMAL(28, 4) NULL COMMENT '资产减值准备(元；现金流量表补充资料 ASSET_IMPAIRMENT,JSON 键名 depreciation 系误名,不是折旧)',
    cash_paid_for_dividends_and_interest                          DECIMAL(28, 4) NULL COMMENT '分配股利、利润或偿付利息支付的现金(元)',
    cash_and_cash_equivalents_end_of_year                         DECIMAL(28, 4) NULL COMMENT '期末现金及现金等价物余额(元)',
    gross_margin                                                  DECIMAL(12, 4) NULL COMMENT '销售毛利率%',
    roe_weighted_excluding_non_recurring_items                    DECIMAL(12, 4) NULL COMMENT '扣非加权平均ROE%',
    return_on_invested_capital                                    DECIMAL(12, 4) NULL COMMENT '投入资本回报率ROIC%',
    return_on_assets                                              DECIMAL(12, 4) NULL COMMENT '总资产净利率(%,净利润/平均总资产)',
    liability_to_asset_ratio                                      DECIMAL(12, 4) NULL COMMENT '资产负债率(%)',
    equity_multiplier                                             DECIMAL(12, 4) NULL COMMENT '权益乘数(倍,总资产/股东权益合计)',
    current_ratio                                                 DECIMAL(12, 4) NULL COMMENT '流动比率(倍)',
    quick_ratio                                                   DECIMAL(12, 4) NULL COMMENT '速动比率(倍)',
    total_asset_turnover                                          DECIMAL(12, 4) NULL COMMENT '总资产周转率(次)',
    operating_cash_flow_to_revenue                                DECIMAL(12, 6) NULL COMMENT '经营活动现金流量净额÷营业收入(小数,非%)',
    eps_excluding_non_recurring_items                             DECIMAL(16, 6) NULL COMMENT '扣非基本每股收益(元/股)',
    employee_count                                                INT            NULL COMMENT '员工人数(人)',
    total_shares                                                  BIGINT         NULL COMMENT '总股本(股,接口当前股本快照逐年回填)',
    effective_tax_rate                                            DECIMAL(12, 4) NULL COMMENT '实际所得税税率%',
    short_term_interest_bearing_debt                              DECIMAL(28, 4) NULL COMMENT '短期有息负债(元)',
    long_term_interest_bearing_debt                               DECIMAL(28, 4) NULL COMMENT '长期有息负债(元)',
    interest_bearing_debt                                         DECIMAL(28, 4) NULL COMMENT '有息负债(元)',
    cash_and_trading_financial_assets                             DECIMAL(28, 4) NULL COMMENT '货币资金+交易性金融资产(元)',
    net_cash_position                                             DECIMAL(28, 4) NULL COMMENT '净现金(元)((货币资金+交易性金融资产)-有息负债)',
    net_gearing_ratio                                             DECIMAL(12, 4) NULL COMMENT '净负债率%((有息负债-现金)÷股东权益合计)',
    fixed_assets_and_construction_in_progress                     DECIMAL(28, 4) NULL COMMENT '固定资产+在建工程(元)',
    fixed_assets_and_construction_in_progress_to_total_assets     DECIMAL(12, 4) NULL COMMENT '重资产度%((固定资产+在建工程)÷总资产)',
    cash_paid_for_long_term_assets_to_revenue                     DECIMAL(12, 4) NULL COMMENT '资本开支强度%(购建长期资产现金÷营业收入)',
    free_cash_flow_proxy                                          DECIMAL(28, 4) NULL COMMENT '自由现金流代理(元)=经营净现金−购建长期资产付现',
    period_expenses                                               DECIMAL(28, 4) NULL COMMENT '期间费用(元)(销售+管理+财务+研发)',
    period_expense_ratio                                          DECIMAL(12, 4) NULL COMMENT '期间费用率%',
    research_and_development_expense_ratio                        DECIMAL(12, 4) NULL COMMENT '研发费用率%(研发费用/营业收入×100)',
    gross_margin_calculated                                       DECIMAL(12, 4) NULL COMMENT '自算毛利率%((营收-营业成本)÷营收)',
    return_on_assets_attr_parent                                  DECIMAL(12, 4) NULL COMMENT '归母总资产收益率(%,归母净利润/期初期末平均总资产,自算)',
    equity_asset_ratio                                            DECIMAL(12, 4) NULL COMMENT '权益资产比(%,股东权益合计/总资产,自算)',
    revenue_per_employee                                          DECIMAL(16, 6) NULL COMMENT '人均营业收入(万元/人)',
    net_profit_attr_parent_per_employee                DECIMAL(16, 6) NULL COMMENT '人均归母净利润(万元/人)',
    main_business_revenue                                         DECIMAL(28, 4) NULL COMMENT '主营业务收入/通信服务收入(元)，不含销售产品',
    other_revenue                                                 DECIMAL(28, 4) NULL COMMENT '其他收入(元)',
    revenue_breakdown_denominator                                 DECIMAL(28, 4) NULL COMMENT '收入拆分分母(元)：2013起主营业务收入，之前营运收入',
    voice_services_revenue                                        DECIMAL(28, 4) NULL COMMENT '语音业务收入(元)',
    monthly_fee_revenue                                           DECIMAL(28, 4) NULL COMMENT '月租费收入(元)；仅2001–2002',
    connection_fee_revenue                                        DECIMAL(28, 4) NULL COMMENT '入网费收入(元)；仅2001–2002',
    short_message_and_multimedia_message_revenue                  DECIMAL(28, 4) NULL COMMENT '短彩信业务收入(元)',
    value_added_services_revenue                                  DECIMAL(28, 4) NULL COMMENT '增值业务收入(元)；2001–2010旧口径',
    data_services_revenue                                         DECIMAL(28, 4) NULL COMMENT '数据业务收入(元)；2011–2020合计口径',
    wireless_data_traffic_revenue                                 DECIMAL(28, 4) NULL COMMENT '无线上网业务收入(元)',
    wireline_broadband_revenue                                    DECIMAL(28, 4) NULL COMMENT '有线宽带业务收入(元)',
    applications_and_information_services_revenue                 DECIMAL(28, 4) NULL COMMENT '应用及信息服务收入(元)',
    other_main_business_revenue                                   DECIMAL(28, 4) NULL COMMENT '主营业务内其他收入(元)',
    communication_services_revenue                                DECIMAL(28, 4) NULL COMMENT '通信服务收入(元)；2025起三大主业口径',
    computing_power_services_revenue                              DECIMAL(28, 4) NULL COMMENT '算力服务收入(元)；2025起三大主业口径',
    intelligent_services_revenue                                  DECIMAL(28, 4) NULL COMMENT '智能服务收入(元)；2025起三大主业口径',
    personal_market_revenue                                       DECIMAL(28, 4) NULL COMMENT '个人市场收入(元)；CHBN 之 C',
    home_market_revenue                                           DECIMAL(28, 4) NULL COMMENT '家庭市场收入(元)；CHBN 之 H',
    government_and_enterprise_market_revenue                      DECIMAL(28, 4) NULL COMMENT '政企市场收入(元)；CHBN 之 B',
    new_business_market_revenue                                   DECIMAL(28, 4) NULL COMMENT '新兴市场收入(元)；CHBN 之 N',
    digital_transformation_revenue                                DECIMAL(28, 4) NULL COMMENT '数字化转型收入(元)；2021–2024',
    profit_from_operations                                        DECIMAL(28, 4) NULL COMMENT '营运利润(元)=营运收入−营运支出(IFRS口径)',
    earnings_before_interest_taxes_depreciation_and_amortization  DECIMAL(28, 4) NULL COMMENT 'EBITDA(元)=营运利润+折旧及摊销',
    capital_expenditure                                           DECIMAL(28, 4) NULL COMMENT '资本开支(元)',
    free_cash_flow                                                DECIMAL(28, 4) NULL COMMENT '自由现金流(元)，公司披露口径',
    operating_expenses                                            DECIMAL(28, 4) NULL COMMENT '营运支出合计(元)，IFRS口径',
    network_operation_and_support_expenses                        DECIMAL(28, 4) NULL COMMENT '网络运营及支撑成本(元)',
    employee_benefit_and_related_expenses                         DECIMAL(28, 4) NULL COMMENT '雇员薪酬及相关成本(元)',
    cost_of_products_sold                                         DECIMAL(28, 4) NULL COMMENT '销售产品成本(元)',
    other_operating_expenses                                      DECIMAL(28, 4) NULL COMMENT '其他营运支出(元)',
    interim_dividend_per_share                                    DECIMAL(16, 6) NULL COMMENT '中期股息(港元/股)',
    final_dividend_per_share                                      DECIMAL(16, 6) NULL COMMENT '末期股息(港元/股)',
    disclosed_dividend_payout_ratio                               DECIMAL(12, 4) NULL COMMENT '派息率%(公司披露，全年股息/股东应占利润)',
    other_data_services_revenue                                   DECIMAL(28, 4) NULL COMMENT '其他数据业务收入(元)；增值业务子项',
    hong_kong_report_operating_revenue                            DECIMAL(28, 4) NULL COMMENT '港股年报口径营业收入(元；港股接口交叉核对值)',
    hong_kong_report_net_profit_attr_parent                       DECIMAL(28, 4) NULL COMMENT '港股年报口径归母净利润(元；港股接口交叉核对值)',
    hong_kong_report_total_assets                                 DECIMAL(28, 4) NULL COMMENT '港股年报口径总资产(元；港股接口交叉核对值)',
    hong_kong_report_equity_attr_parent                           DECIMAL(28, 4) NULL COMMENT '港股年报口径归母股东权益(元；港股接口交叉核对值)',
    hong_kong_report_basic_eps                                    DECIMAL(16, 6) NULL COMMENT '港股年报口径基本每股收益(港股接口 BASIC_EPS)',
    hong_kong_report_return_on_average_equity                     DECIMAL(12, 4) NULL COMMENT '港股年报口径平均净资产收益率%(港股接口 ROE_AVG)',
    hong_kong_report_dividend_payout_ratio                        DECIMAL(12, 6) NULL COMMENT '港股接口派息率原值(DIVI_RATIO,小数；量纲未逐年核实)',
    depreciation_and_amortization                                 DECIMAL(28, 4) NULL COMMENT '折旧及摊销(元；中国移动港股年报营运支出分项,原文百万元)',
    revenue_fields_mismatch                                       TINYINT(1)     NULL COMMENT '1=接口营业收入与营业总收入字段矛盾,该年收入类比率已置空',
    disclosure_source                                             VARCHAR(8)     NULL COMMENT '披露来源 A=A股年报口径/PRE=上市前回填(H股年报/招股材料),两段不拼接',
    report_basis                                                  VARCHAR(16)    NULL COMMENT '该年取数的年报(港股年报/A股年报)',
    caliber_note                                                  TEXT           NULL COMMENT '该年口径说明原文',
    restatement_note                                              TEXT           NULL COMMENT '重列说明原文',
    revenue_breakdown_layers                                      TEXT           NULL COMMENT '收入拆分堆叠的分项字段名(逗号分隔,相加=revenue_breakdown_denominator)',
    source                                                        TEXT           NULL COMMENT '数据来源',
    PRIMARY KEY (company_code, fiscal_year),
    CONSTRAINT fk_telecom_financials_company FOREIGN KEY (company_code) REFERENCES company (company_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT ='电信运营业专属年度指标（telecom_*_annual.json 里 financials 公共列以外的字段）：与 financials 同主键按需 JOIN，公共列不在此重复；JSON 源字段名与倍数见 data/extract/industry_columns.py，金额统一为元；中国移动港股年报序列（hk.00941）手工摘录字段原文为人民币百万元，入库 ×1e6，每股股息为港元/股不换算';
